void close_handle(uv_handle_t* handle) {
  switch (handle->type) {
    case UV_ASYNC:
      static_cast<AsyncHandle*>(handle->data)->close();
      break;
    case UV_FS_EVENT:
      static_cast<FSEventHandle*>(handle->data)->close();
      break;
    case UV_POLL:
      static_cast<PollHandle*>(handle->data)->close();
      break;
    case UV_TIMER:
      static_cast<TimerHandle*>(handle->data)->close();
      break;
    case UV_SIGNAL:
      static_cast<SignalHandle*>(handle->data)->close();
      break;
    case UV_NAMED_PIPE:
      static_cast<PipeHandle*>(handle->data)->close();
      break;
    case UV_PREPARE:
      static_cast<PrepareHandle*>(handle->data)->close();
      break;
    default:
      assert(false);
  }
}

static void doAdvicesChain(
    const std::vector<std::function<void(const HttpRequestPtr &,
                                         AdviceCallback &&,
                                         AdviceChainCallback &&)>> &advices,
    size_t index,
    const HttpRequestImplPtr &req,
    std::shared_ptr<const std::function<void(const HttpResponsePtr &)>>
        &&callbackPtr)
{
    if (index < advices.size())
    {
        auto &advice = advices[index];
        advice(
            req,
            [/*copy*/ callbackPtr](const HttpResponsePtr &resp) {
                (*callbackPtr)(resp);
            },
            [index, req, callbackPtr, &advices]() mutable {
                auto ioLoop = req->getLoop();
                if (ioLoop && !ioLoop->isInLoopThread())
                {
                    ioLoop->queueInLoop([index,
                                         req,
                                         callbackPtr = std::move(callbackPtr),
                                         &advices]() mutable {
                        doAdvicesChain(advices,
                                       index + 1,
                                       req,
                                       std::move(callbackPtr));
                    });
                }
                else
                {
                    doAdvicesChain(advices,
                                   index + 1,
                                   req,
                                   std::move(callbackPtr));
                }
            });
    }
    else
    {
        (*callbackPtr)(nullptr);
    }
}

